"""tone -- keyed spectral beacon, DETECTOR ONLY.

For each secret frequency (a pure function of the key and the committed counters), compare the Hann-tapered spectral
power at f with the mean power of NREF reference bins around it; p = (1 + r/N)^-N; tones combined with Fisher.
Its parametric p-value is NOT valid on data with natural spectral lines, so tone is information only and never part of
a decision (core.INFO_ONLY_METHODS; docs/FORMAL.md N1). An attacker who finds a line can notch it out.
"""
from __future__ import annotations

import numpy as np
import pandas as pd
from scipy import stats
from ..prf import domain_id, prf_unit


NAME = "tone"


NREF = 64


def tone_freq(key: bytes, col: str, counter: int, f_lo: float, f_hi: float) -> float:
    u = float(prf_unit(key, domain_id("tone:" + col), np.array([counter]))[0])
    return float(np.exp(np.log(f_lo) + u * (np.log(f_hi) - np.log(f_lo))))


def _power(x, t, f, win):
    ph = np.exp(-2j * np.pi * f * t)
    return float(np.abs(np.sum(win * x * ph)) ** 2)


def _prep(x, t):
    ok = np.isfinite(x) & np.isfinite(t)
    x, t = x[ok], t[ok]
    o = np.argsort(t, kind="stable")
    x, t = x[o], t[o]
    T = t[-1] - t[0]
    t = t - t[0]
    x = x - x.mean()
    win = 0.5 * (1 - np.cos(2 * np.pi * (t / T + 0.5 / max(len(t), 1)))) if T > 0 else np.ones_like(t)
    return x, t, win, T


def _ref_freqs(f, T):
    bins = 2.0 / T
    offs = np.arange(4, 4 + 2 * (NREF // 2), 2) * 0.5 * bins * 1.0
    refs = np.concatenate([f - offs, f + offs])
    return refs[refs > 0]


def ratio(x, t, f, win, T):
    refs = _ref_freqs(f, T)
    pr = np.array([_power(x, t, fr, win) for fr in refs])
    return _power(x, t, f, win) / max(pr.mean(), 1e-300), len(refs)


def tone_p(r: float, nref: int) -> float:
    return float((1 + r / nref) ** (-nref))


SHARED = "__shared__"


def freq_col(params: dict, col: str) -> str:
    """Key-stream label used to derive a column's tone frequencies."""
    return SHARED if params.get("shared") else col


def detect(df: pd.DataFrame, key: bytes, t: np.ndarray, params: dict, **_):
    flo, fhi = params["band"]
    per, ps = {}, []
    for c, cp in params["columns"].items():
        if c not in df.columns or not cp["counters"]:
            per[c] = {"missing": True}
            continue
        xs, ts, win, T = _prep(df[c].to_numpy(dtype=np.float64), t)
        if xs.size < 256:
            per[c] = {"skipped": True}
            continue
        tones = []
        for ctr in cp["counters"]:
            f = tone_freq(key, freq_col(params, c), ctr, flo, fhi)
            if f > 0.5 / max(np.median(np.diff(ts)), 1e-12) * 1.0 or 1.0 / T > f / 3:
                continue  # beyond Nyquist of this copy (downsampled) or < 3 cycles in the record
            r, nref = ratio(xs, ts, f, win, T)
            tones.append({"freq": f, "ratio": r, "p": tone_p(r, nref)})
            ps.append(tone_p(r, nref))
        per[c] = {"tones": tones}
    if not ps:
        return {"method": NAME, "columns": per, "z": 0.0, "p": 1.0}
    stat = -2 * np.sum(np.log(np.maximum(ps, 1e-300)))
    p = float(stats.chi2.sf(stat, 2 * len(ps)))
    return {"method": NAME, "columns": per, "z": float(stats.norm.isf(max(p, 1e-300))), "p": p}
